#pragma once#include "ISignalTags.h"#include <vector>class KSignalTag : public TIntrusivePtrImpl<ISignalTag>{public:  KSignalTag();protected:  virtual void SetDecPics( int dp );  virtual int GetDecPics();  virtual void SetDescription( LPCSTR pszDescr );  virtual LPCSTR GetDescription() const;  virtual void SetUnits( LPCSTR pszUnits );  virtual LPCSTR GetUnits() const;  virtual void SetAccess( LPCSTR pszA );  virtual void SetDataType( LPCSTR pszDT );  virtual void SetNumber( int n );  virtual int GetNumber();  virtual void SetInitialSourceValue( LPCSTR pszIS );  virtual LPCSTR GetInitialSourceValue();  virtual void SetBlockOut( short blk, short out );protected:  int m_DecPics, m_Number;  std::string m_szDescr, m_szEU, m_szAccess, m_szDataType, m_szInitialSource;  short m_Block, m_Out;};//////////////////////////////////////////////////////////////////////////class KAnalogSignalTag : public KSignalTag{public:  KAnalogSignalTag();  KAnalogSignalTag( std::vector<std::string> &params );protected:  virtual LPCSTR GetType() const  {    return "AnalogSignalTag";  }  virtual bool IsAnalog()  {    return true;  }  virtual LPCSTR GetOnLabel()  {    return NULL;  }  virtual LPCSTR GetOffLabel()  {    return NULL;  }};//////////////////////////////////////////////////////////////////////////class KDigitalSignalTag : public KSignalTag{public:  KDigitalSignalTag();  KDigitalSignalTag( std::vector<std::string> &params );  void SetOnLabel( LPCSTR pszV )  {    szOn = pszV;  }  void SetOffLabel( LPCSTR pszV )  {    szOff = pszV;  }protected:  virtual LPCSTR GetType() const  {    return "DigitalSignalTag";  }  virtual bool IsAnalog()  {    return false;  }  virtual LPCSTR GetOnLabel()  {    return szOn.c_str();  }  virtual LPCSTR GetOffLabel()  {    return szOff.c_str();  }protected:  std::string szOn, szOff;};